    H = len(grid)
    W = len(grid[0]) if H else 0

    # Background value = the largest number in the grid
    background = max(val for row in grid for val in row)

    # Find bounding box of all cells that are not the background (including zeros)
    r_min = H
    r_max = -1
    c_min = W
    c_max = -1
    for i in range(H):
        for j in range(W):
            if grid[i][j] != background:
                if i < r_min:
                    r_min = i
                if i > r_max:
                    r_max = i
                if j < c_min:
                    c_min = j
                if j > c_max:
                    c_max = j

    # If the whole grid is background, return an empty grid (should not happen)
    if r_min > r_max or c_min > c_max:
        return [[]]

    nr = r_max - r_min + 1          # height of the non‑background region
    nc = c_max - c_min + 1          # width of the non‑background region

    # Build the template B (size H×H) from the background region
    B = [[0] * H for _ in range(H)]

    # Determine whether the background region lies on the top/left or bottom/right
    row_bg_top = r_min > 0          # background rows are above the box
    col_bg_left = c_min > 0         # background columns are left of the box

    for i in range(H):
        for j in range(W):
            if grid[i][j] == background:
                # map to the H×H template
                if row_bg_top:
                    ti = i
                else:
                    ti = i - nr      # background is below the box
                if col_bg_left:
                    tj = j
                else:
                    tj = j - nc      # background is to the right of the box
                if 0 <= ti < H and 0 <= tj < H:
                    B[ti][tj] = background

    # Create output grid of size H*H × H*H
    size = H * H
    out = [[0] * size for _ in range(size)]

    # Fill a block for each non‑zero, non‑background cell
    for i in range(H):
        for j in range(W):
            val = grid[i][j]
            if val != background and val != 0:
                block_i = i - r_min
                block_j = j - c_min
                # copy the template B, replacing the background value by the cell value
                for bi in range(H):
                    for bj in range(H):
                        if B[bi][bj] == background:
                            out[block_i * H + bi][block_j * H + bj] = val

    return out

